PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?avgHoldings ?avgRebalancingActions ?avgRiskScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .

  # Calculate average number of holdings
  {
    SELECT COUNT(?holding) AS ?numHoldings
    WHERE {
      ?investor wm:hasHolding ?holding .
    }
  }

  # Calculate average number of rebalancing actions
  {
    SELECT AVG(?numRebalancingActions) AS ?avgRebalancingActions
    WHERE {
      ?investor wm:hasRebalancingAction ?rebalancingAction .
      {
        SELECT COUNT(?rebalancingAction) AS ?numRebalancingActions
        WHERE {
          ?investor wm:hasRebalancingAction ?rebalancingAction .
        }
      }
    }
  }

  # Calculate average risk score
  {
    SELECT AVG(?riskScore) AS ?avgRiskScore
    WHERE {
      ?investor wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScore .
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?avgHoldings ?avgCashFlow ?avgRiskScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .

  # Calculate average number of holdings
  {
    SELECT ?riskTolerance (AVG(?holdingCount) AS ?avgHoldings)
    WHERE {
      ?investor wm:hasHolding ?holding .
      BIND (COUNT(?holding) AS ?holdingCount)
    }
    GROUP BY ?riskTolerance
  }

  # Calculate average net cash flow
  {
    SELECT ?riskTolerance (AVG(?netCashFlow) AS ?avgCashFlow)
    WHERE {
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
      BIND (?amount AS ?netCashFlow)
    }
    GROUP BY ?riskTolerance
  }

  # Calculate average risk score
  {
    SELECT ?riskTolerance (AVG(?riskScore) AS ?avgRiskScore)
    WHERE {
      ?investor wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScore .
    }
    GROUP BY ?riskTolerance
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizon ?avgHoldings ?avgCashFlow ?avgRiskScore
WHERE {
  ?investor wm:hasTimeHorizon ?timeHorizon .

  # Calculate average number of holdings per investor
  {
    SELECT ?timeHorizon (AVG(?holdingCount) AS ?avgHoldings)
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?timeHorizon wm:timeHorizon ?timeHorizonValue .
      BIND (COUNT(?holding) AS ?holdingCount)
      FILTER (?timeHorizon = ?timeHorizon)
    }
    GROUP BY ?timeHorizon
  }

  # Calculate average net cash flow per investor
  {
    SELECT ?timeHorizon (AVG(?netCashFlow) AS ?avgCashFlow)
    WHERE {
      ?investor wm:hasCashFlow ?cashFlow .
      ?timeHorizon wm:timeHorizon ?timeHorizonValue .
      BIND (?cashFlow.amount AS ?cashFlowAmount)
      BIND (?cashFlowAmount AS ?netCashFlow)
      FILTER (?timeHorizon = ?timeHorizon)
    }
    GROUP BY ?timeHorizon
  }

  # Calculate average risk score per investor
  {
    SELECT ?timeHorizon (AVG(?riskScore) AS ?avgRiskScore)
    WHERE {
      ?investor wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScore .
      ?timeHorizon wm:timeHorizon ?timeHorizonValue .
      FILTER (?timeHorizon = ?timeHorizon)
    }
    GROUP BY ?timeHorizon
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?timeHorizon ?avgHoldings ?avgRebalancingActions ?avgRiskScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:hasTimeHorizon ?timeHorizon .

  {
    SELECT COUNT(?holding) AS ?avgHoldings
    WHERE {
      ?investor wm:hasHolding ?holding .
    }
  }

  {
    SELECT AVG(?rebalancingCount) AS ?avgRebalancingActions
    WHERE {
      ?investor wm:hasRebalancingAction ?rebalancingAction .
      BIND (COUNT(?rebalancingAction) AS ?rebalancingCount)
    }
  }

  {
    ?portfolioHealth a wm:PortfolioHealth .
    ?portfolioHealth wm:healthOfInvestor ?investor .
    ?portfolioHealth wm:riskScore ?riskScore .
    SELECT AVG(?riskScore) AS ?avgRiskScore
    WHERE {
      ?portfolioHealth wm:riskScore ?riskScore .
    }
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?avgSectorAllocation ?avgHoldingReturn ?avgRiskScore
WHERE {
  ?investor wm:hasRiskTolerance ?riskTolerance .

  # Calculate average total sector-allocation investment amount per investor
  {
    SELECT ?investorId ?avgSectorAllocation
    WHERE {
      ?investorId wm:hasSectorAllocation ?sectorAllocation .
      ?sectorAllocation wm:totalInvestment ?investmentAmount .
    }
    GROUP BY ?investorId
    BIND (AVG(?investmentAmount) AS ?avgSectorAllocation)
  } -> ?avgSectorAllocationSubquery

  # Calculate average holding return per investor (with cost and current value)
  {
    SELECT ?investorId ?avgHoldingReturn
    WHERE {
      ?investorId wm:hasHolding ?holding .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currentValue .
      BIND ((?currentValue - ?cost) / ?cost * 100 AS ?holdingReturn)
    }
    GROUP BY ?investorId
    BIND (AVG(?holdingReturn) AS ?avgHoldingReturn)
  } -> ?avgHoldingReturnSubquery

  # Calculate average risk score per investor
  {
    SELECT ?investorId ?avgRiskScore
    WHERE {
      ?investorId wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
    BIND (AVG(?riskScore) AS ?avgRiskScore)
  } -> ?avgRiskScoreSubquery

  # Join the results
  ?investor ?avgSectorAllocationSubquery ?avgHoldingReturnSubquery ?avgRiskScoreSubquery .

  BIND (?riskTolerance AS ?riskTolerance)
  BIND (?avgSectorAllocationSubquery.avgSectorAllocation AS ?avgSectorAllocation)
  BIND (?avgHoldingReturnSubquery.avgHoldingReturn AS ?avgHoldingReturn)
  BIND (?avgRiskScoreSubquery.avgRiskScore AS ?avgRiskScore)
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment ?avgHoldings ?avgRebalancingActions ?avgRiskScore
WHERE {
  # Calculate average number of holdings per investor
  SELECT ?segment AVG(?holdingsCount) AS ?avgHoldings
  WHERE {
    ?investor wm:segment ?segment .
    ?investor wm:hasHolding ?holding .
    BIND (COUNT(?holding) AS ?holdingsCount)
  }
  GROUP BY ?segment

  # Calculate average number of rebalancing actions per investor
  SELECT ?segment AVG(?rebalancingActionsCount) AS ?avgRebalancingActions
  WHERE {
    ?investor wm:segment ?segment .
    OPTIONAL { ?investor wm:hasRebalancingAction ?rebalancingAction . }
    BIND (IF(BOUND(?rebalancingAction), 1, 0) AS ?rebalancingActionsCount)
  }
  GROUP BY ?segment

  # Calculate average risk score per investor
  SELECT ?segment AVG(?riskScore) AS ?avgRiskScore
  WHERE {
    ?investor wm:segment ?segment .
    ?investor wm:hasRiskTolerance ?riskTolerance .
    ?riskTolerance wm:riskScore ?riskScore .
  }
  GROUP BY ?segment
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?category ?avgHoldings ?avgRebalancingActions ?avgRiskScore
WHERE {
  # Calculate average holdings per investor for each category
  {
    SELECT ?category AVG(COUNT(?holdingId)) AS ?avgHoldings
    WHERE {
      ?investor a wm:Investor ;
                wm:hasCategory ?category ;
                wm:hasHolding ?holding .
      ?holding wm:holdingId ?holdingId .
    }
    GROUP BY ?category
  }
  # Calculate average rebalancing actions per investor for each category
  {
    SELECT ?category AVG(COUNT(?rebalanceId)) AS ?avgRebalancingActions
    WHERE {
      ?investor a wm:Investor ;
                wm:hasCategory ?category ;
                wm:hasRebalancingAction ?rebalancingAction .
      ?rebalancingAction wm:rebalanceId ?rebalanceId .
    }
    GROUP BY ?category
  }
  # Calculate average risk score per investor for each category
  {
    SELECT ?category AVG(?riskScore) AS ?avgRiskScore
    WHERE {
      ?investor a wm:Investor ;
                wm:hasCategory ?category ;
                wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScore .
    }
    GROUP BY ?category
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT
  ?category ?avgHoldings ?avgCashFlow ?avgRiskScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:hasCategory ?category .

  # Calculate average number of holdings
  {
    SELECT
      ?category (AVG(?holdingCount) AS ?avgHoldings)
    WHERE {
      ?investor wm:hasHolding ?holding .
      BIND (COUNT(?holding) AS ?holdingCount)
      ?investor wm:hasCategory ?category .
    }
    GROUP BY ?category
  }

  # Calculate average net cash flow
  {
    SELECT
      ?category (AVG(?netCashFlow) AS ?avgCashFlow)
    WHERE {
      ?investor wm:hasCashFlow ?cashFlow .
      ?cashFlow wm:amount ?amount .
      BIND (?amount AS ?netCashFlow)
      ?investor wm:hasCategory ?category .
    }
    GROUP BY ?category
  }

  # Calculate average risk score
  {
    SELECT
      ?category (AVG(?riskScore) AS ?avgRiskScore)
    WHERE {
      ?investor wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScore .
      ?investor wm:hasCategory ?category .
    }
    GROUP BY ?category
  }
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?category ?avgSectorAllocation ?avgHoldingReturn ?avgRiskScore
WHERE {
  ?investor wm:hasCategory ?category .

  # Calculate average sector allocation investment amount per investor
  {
    SELECT ?investor ?avgSectorAllocation
    WHERE {
      ?investor wm:hasSectorAllocation ?sectorAllocation .
      ?sectorAllocation wm:totalInvestment ?investmentAmount .
      BIND (AVG(?investmentAmount) AS ?avgSectorAllocation)
    }
    GROUP BY ?investor
  }

  # Calculate average holding return per investor (with cost and current value)
  {
    SELECT ?investor ?avgHoldingReturn
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currentValue .
      FILTER (?cost > 0 && ?currentValue >= 0)
      BIND (((?currentValue - ?cost) / ?cost * 100) AS ?holdingReturn)
      BIND (AVG(?holdingReturn) AS ?avgHoldingReturn)
    }
    GROUP BY ?investor
  }

  # Calculate average risk score per investor
  {
    SELECT ?investor ?avgRiskScore
    WHERE {
      ?investor wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:riskScore ?riskScore .
      BIND (AVG(?riskScore) AS ?avgRiskScore)
    }
    GROUP BY ?investor
  }
}
GROUP BY ?category

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?avgNetCashFlow ?avgSignedCashFlow ?avgCashFlowCount
WHERE {
  ?investor a wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .
  ?cashFlow wm:cashFlowOfInvestor ?investor .
  ?cashFlow wm:amount ?amount .

  # Calculate net cash flow (sum of inflows - sum of outflows)
  {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?investorId a wm:Investor .
      ?cashFlow1 wm:cashFlowOfInvestor ?investorId .
      ?cashFlow1 wm:amount ?amount1 .
      FILTER (?amount1 < 0)  # Inflow
      BIND (SUM(?amount1) AS ?netCashFlow)
    }
    GROUP BY ?investorId
  }
  BIND (?netCashFlow AS ?avgNetCashFlow)

  # Calculate average signed cash flow amount
  {
    SELECT ?investorId ?avgSignedCashFlow
    WHERE {
      ?investorId a wm:Investor .
      ?cashFlow2 wm:cashFlowOfInvestor ?investorId .
      ?cashFlow2 wm:amount ?amount2 .
      BIND (AVG(?amount2) AS ?avgSignedCashFlow)
    }
    GROUP BY ?investorId
  }
  BIND (?avgSignedCashFlow AS ?avgSignedCashFlow)

  # Calculate average cash flow count
  {
