PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  # Calculate net cash flow
  OPTIONAL {
    SELECT ?investorId (SUM(?amount) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow ;
        wm:cashFlowOfInvestor ?investorId ;
        wm:amount ?amount .
    }
    GROUP BY ?investorId
  }

  # Calculate total scenario allocation shift
  OPTIONAL {
    SELECT ?investorId (SUM(?allocationShift) AS ?totalAllocationShift)
    WHERE {
      ?scenarioRebalancing a wm:ScenarioRebalancing ;
        wm:scenarioRebalancingOfInvestor ?investorId ;
        wm:currentAllocationPct ?currentAllocationPct ;
        wm:newAllocationPct ?newAllocationPct .
      BIND (?newAllocationPct - ?currentAllocationPct AS ?allocationShift)
    }
    GROUP BY ?investorId
  }

  # Combine and calculate composite score
  BIND(
    IF(
      BOUND(?netCashFlow) && BOUND(?totalAllocationShift),
      100 * ((?netCashFlow - (SELECT MIN(?netCashFlow) FROM wm:CashFlow WHERE ?cashFlow a wm:CashFlow)) / ((SELECT MAX(?netCashFlow) FROM wm:CashFlow WHERE ?cashFlow a wm:CashFlow) - (SELECT MIN(?netCashFlow) FROM wm:CashFlow WHERE ?cashFlow a wm:CashFlow)) + (?totalAllocationShift - (SELECT MIN(?totalAllocationShift) FROM wm:ScenarioRebalancing WHERE ?scenarioRebalancing a wm:ScenarioRebalancing)) / ((SELECT MAX(?totalAllocationShift) FROM wm:ScenarioRebalancing WHERE ?scenarioRebalancing a wm:ScenarioRebalancing) - (SELECT MIN(?totalAllocationShift) FROM wm:ScenarioRebalancing WHERE ?scenarioRebalancing a wm:ScenarioRebalancing))) / 2,
      0  # Default to 0 if either component is missing
    ) AS ?compositeScore
  )

  ?investor a wm:Investor ;
    wm:investorId ?investorId .

}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  ?cashFlow wm:cashFlowOfInvestor ?investor .
  ?cashFlow wm:amount ?cashFlowAmount .
  ?portfolioHealth wm:healthOfInvestor ?investor .
  ?portfolioHealth wm:riskScore ?riskScore .

  # Calculate net cash flow
  BIND (SUM(?cashFlowAmount) AS ?netCashFlow)

  # Min-max normalization for net cash flow
  BIND (
    COALESCE(
      ( ?netCashFlow - (MIN(?allCashFlowAmounts) AS ?minCashFlow) ) / ( (MAX(?allCashFlowAmounts) AS ?maxCashFlow) - ?minCashFlow ),
      0
    ) AS ?normalizedNetCashFlow
  )

  # Min-max normalization for risk score
  BIND (
    COALESCE(
      ( ?riskScore - (MIN(?allRiskScores) AS ?minRiskScore) ) / ( (MAX(?allRiskScores) AS ?maxRiskScore) - ?minRiskScore ),
      0
    ) AS ?normalizedRiskScore
  )

  # Calculate composite score
  BIND (100 * ( ?normalizedNetCashFlow + ?normalizedRiskScore) / 2 AS ?compositeScore)

  # Find min and max values for normalization
  {
    SELECT MIN(?cashFlowAmount) AS ?minCashFlow MAX(?cashFlowAmount) AS ?maxCashFlow
    WHERE {
      ?cf a wm:CashFlow .
      ?cf wm:amount ?cashFlowAmount .
    }
  }

  {
    SELECT MIN(?riskScore) AS ?minRiskScore MAX(?riskScore) AS ?maxRiskScore
    WHERE {
      ?ph a wm:PortfolioHealth .
      ?ph wm:riskScore ?riskScore .
    }
  }
}
GROUP BY ?investorId ?compositeScore
ORDER BY ?compositeScore DESC ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  # Calculate total holding gain
  OPTIONAL {
    SELECT ?investorId (SUM(?gain) AS ?totalGain)
    WHERE {
      ?holding a wm:PortfolioHolding ;
        wm:heldByInvestor ?investor ;
        wm:cost ?cost ;
        wm:currentValue ?currentValue .
      BIND(?currentValue - ?cost AS ?gain)
      ?investor a wm:Investor ;
        wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  # Calculate total scenario allocation shift
  OPTIONAL {
    SELECT ?investorId (SUM(?shift) AS ?totalShift)
    WHERE {
      ?rebalancingAction a wm:RebalancingAction ;
        wm:rebalancingActionOfInvestor ?investor ;
        wm:currentAllocationPct ?currentAllocationPct ;
        wm:targetAllocationPct ?targetAllocationPct .
      BIND(?targetAllocationPct - ?currentAllocationPct AS ?shift)
      ?investor a wm:Investor ;
        wm:investorId ?investorId .
    }
    GROUP BY ?investorId
  }

  # Combine and calculate composite score
  BIND(IF(BOUND(?totalGain) && BOUND(?totalShift),
           100 * (0.5 * ((?totalGain - (MIN(?totalGain) OVER()) / (MAX(?totalGain) OVER() - MIN(?totalGain) OVER())) + 0.5 * ((?totalShift - (MIN(?totalShift) OVER()) / (MAX(?totalShift) OVER() - MIN(?totalShift) OVER())))),
           0) AS ?compositeScore)

  ?investor a wm:Investor ;
    wm:investorId ?investorId .
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?avgNetCashFlow ?avgCashFlowAmount ?avgTotalHoldingValue ?avgRiskScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .

  # Calculate net cash flow per investor
  {
    SELECT ?investorId (SUM(?cashFlowAmount) AS ?netCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?cashFlowAmount .
      ?cashFlow wm:type ?cashFlowType .
      FILTER (STRSTARTS(STR(?cashFlowType), "Deposit") || STRSTARTS(STR(?cashFlowType), "SIP")) # Inflows
      BIND (?cashFlowAmount AS ?inflow)
    }
    UNION
    {
      SELECT ?investorId (SUM(-?cashFlowAmount) AS ?netCashFlow)
      WHERE {
        ?cashFlow a wm:CashFlow .
        ?cashFlow wm:cashFlowOfInvestor ?investor .
        ?cashFlow wm:amount ?cashFlowAmount .
        ?cashFlow wm:type ?cashFlowType .
        FILTER (STRSTARTS(STR(?cashFlowType), "Withdrawal") || STRSTARTS(STR(?cashFlowType), "Redemption")) # Outflows
        BIND (-?cashFlowAmount AS ?inflow)
      }
    }
    BIND (?investorId AS ?investorId)
  } AS ?netCashFlowData

  # Calculate total holding value per investor
  {
    SELECT ?investorId (SUM(?currentValue) AS ?totalHoldingValue)
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:currentValue ?currentValue .
    }
    BIND (?investorId AS ?investorId)
  } AS ?holdingValueData

  # Get risk score per investor
  {
    SELECT ?investorId ?riskScore
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth .
      ?portfolioHealth wm:healthOfInvestor ?investor .
      ?portfolioHealth wm:riskScore ?riskScore .
    }
    BIND (?investorId AS ?investorId)
  } AS ?riskScoreData

  # Join the data
  BIND (?investorId AS ?investorId)

  OPTIONAL {
    SELECT ?investorId ?netCashFlow FROM ?netCashFlowData
  }
  OPTIONAL {
    SELECT ?investorId ?totalHoldingValue FROM ?holdingValueData
  }
  OPTIONAL {
    SELECT ?investorId ?riskScore FROM ?riskScoreData
  }

  # Calculate averages
  SELECT ?riskTolerance AVG(?netCashFlow) AS ?avgNetCashFlow AVG(?totalHoldingValue) AS ?avgTotalHoldingValue AVG(?riskScore) AS ?avgRiskScore
  WHERE {
    ?investor a wm:Investor .
    ?investor wm:riskTolerance ?riskTolerance .

    OPTIONAL {
      SELECT ?netCashFlow FROM ?netCashFlowData WHERE { ?netCashFlowData wm:cashFlowOfInvestor ?investor }
    }
    OPTIONAL {
      SELECT ?totalHoldingValue FROM ?holdingValueData WHERE { ?holdingValueData wm:heldByInvestor ?investor }
    }
    OPTIONAL {
      SELECT ?riskScore FROM ?riskScoreData WHERE { ?riskScoreData wm:healthOfInvestor ?investor }
    }
  }
  GROUP BY ?riskTolerance
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?avgNetCashFlow ?avgSignedCashFlowAmount ?avgTotalHoldingValue ?avgTotalSectorInvestment
WHERE {
  ?investor a wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .

  # Calculate net cash flow per investor
  {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investorId .
      ?cashFlow wm:amount ?amount .
      FILTER (?amount > 0)  # Inflows
    }
    GROUP BY ?investorId
    BIND (SUM(?amount) AS ?netCashFlow)
  } AS %inflows

  {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investorId .
      ?cashFlow wm:amount ?amount .
      FILTER (?amount < 0)  # Outflows
    }
    GROUP BY ?investorId
    BIND (SUM(?amount) AS ?netCashFlow)
  } AS %outflows

  BIND (COALESCE(?inflows:netCashFlow, 0) + COALESCE(?outflows:netCashFlow, 0) AS ?netCashFlow)

  # Calculate average signed cash flow amount
  {
    SELECT ?investorId ?signedCashFlowAmount
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investorId .
      ?cashFlow wm:amount ?amount .
      BIND (?amount AS ?signedCashFlowAmount)
    }
    GROUP BY ?investorId
    BIND (AVG(?signedCashFlowAmount) AS ?signedCashFlowAmount)
  }

  # Calculate average total holding value
  {
    SELECT ?investorId ?totalHoldingValue
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investorId .
      ?holding wm:currentValue ?currentValue .
      BIND (?currentValue AS ?totalHoldingValue)
    }
    GROUP BY ?investorId
    BIND (SUM(?totalHoldingValue) AS ?totalHoldingValue)
  }

  # Calculate average total sector investment
  {
    SELECT ?investorId ?totalSectorInvestment
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investorId .
      ?holding wm:sector ?sector .
      ?holding wm:currentValue ?currentValue .
      BIND (?currentValue AS ?totalSectorInvestment)
    }
    GROUP BY ?investorId ?sector
    BIND (SUM(?totalSectorInvestment) AS ?totalSectorInvestment)
  }

  BIND (?investorId AS ?investorId)

  ?investor wm:investorId ?investorId

  # Aggregate results
  SELECT ?riskTolerance AVG(?netCashFlow) AS ?avgNetCashFlow AVG(?signedCashFlowAmount) AS ?avgSignedCashFlowAmount AVG(?totalHoldingValue) AS ?avgTotalHoldingValue AVG(?totalSectorInvestment) AS ?avgTotalSectorInvestment
  WHERE {
    ?investor a wm:Investor .
    ?investor wm:riskTolerance ?riskTolerance .
    ?investor wm:investorId ?investorId .

    # Calculate net cash flow per investor
    {
      SELECT ?investorId ?netCashFlow
      WHERE {
        ?cashFlow a wm:CashFlow .
        ?cashFlow wm:cashFlowOfInvestor ?investorId .
        ?cashFlow wm:amount ?amount .
        FILTER (?amount > 0)  # Inflows
      }
      GROUP BY ?investorId
      BIND (SUM(?amount) AS ?netCashFlow)
    } AS %inflows

    {
      SELECT ?investorId ?netCashFlow
      WHERE {
        ?cashFlow a wm:CashFlow .
        ?cashFlow wm:cashFlowOfInvestor ?investorId .
        ?cashFlow wm:amount ?amount .
        FILTER (?amount < 0)  # Outflows
      }
      GROUP BY ?investorId
      BIND (SUM(?amount) AS ?netCashFlow)
    } AS %outflows

    BIND (COALESCE(?inflows:netCashFlow, 0) + COALESCE(?outflows:netCashFlow, 0) AS ?netCashFlow)

    # Calculate average signed cash flow amount
    {
      SELECT ?investorId ?signedCashFlowAmount
      WHERE {
        ?cashFlow a wm:CashFlow .
        ?cashFlow wm:cashFlowOfInvestor ?investorId .
        ?cashFlow wm:amount ?amount .
        BIND (?amount AS ?signedCashFlowAmount)
      }
      GROUP BY ?investorId
      BIND (AVG(?signedCashFlowAmount) AS ?signedCashFlowAmount)
    }

    # Calculate average total holding value
    {
      SELECT ?investorId ?totalHoldingValue
      WHERE {
        ?holding a wm:PortfolioHolding .
        ?holding wm:heldByInvestor ?investorId .
        ?holding wm:currentValue ?currentValue .
        BIND (?currentValue AS ?totalHoldingValue)
      }
      GROUP BY ?investorId
      BIND (SUM(?totalHoldingValue) AS ?totalHoldingValue)
    }

    # Calculate average total sector investment
    {
      SELECT ?investorId ?totalSectorInvestment
      WHERE {
        ?holding a wm:PortfolioHolding .
        ?holding wm:heldByInvestor ?investorId .
        ?holding wm:sector ?sector .
        ?holding wm:currentValue ?currentValue .
        BIND (?currentValue AS ?totalSectorInvestment)
      }
      GROUP BY ?investorId ?sector
      BIND (SUM(?totalSectorInvestment) AS ?totalSectorInvestment)
    }
  }
  GROUP BY ?riskTolerance
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?avgNetCashFlow ?avgCashFlowAmount ?avgScenarioAllocationShift ?avgRiskScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:riskTolerance ?riskTolerance .

  # Calculate net cash flow
  {
    SELECT ?investorId (AVG(?cashFlowAmount) AS ?avgNetCashFlow)
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investorId .
      ?cashFlow wm:amount ?cashFlowAmount .
      FILTER (?cashFlowAmount < 0)  # Inflows are negative
    }
    GROUP BY ?investorId
  }

  # Calculate average cash flow amount
  {
    SELECT ?investorId (AVG(ABS(?cashFlowAmount)) AS ?avgCashFlowAmount)
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investorId .
      ?cashFlow wm:amount ?cashFlowAmount .
    }
    GROUP BY ?investorId
  }

  # Calculate average scenario allocation shift
  {
    SELECT ?investorId (AVG(?scenarioAllocationShift) AS ?avgScenarioAllocationShift)
    WHERE {
      ?scenarioRebalancing a wm:ScenarioRebalancing .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investorId .
      ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct .
      ?scenarioRebalancing wm:currentAllocationPct ?currentAllocationPct .
      BIND (?newAllocationPct - ?currentAllocationPct AS ?scenarioAllocationShift)
    }
    GROUP BY ?investorId
  }

  # Calculate average risk score
  {
    SELECT ?investorId (AVG(?riskScore) AS ?avgRiskScore)
    WHERE {
      ?portfolioHealth a wm:PortfolioHealth .
      ?portfolioHealth wm:healthOfInvestor ?investorId .
      ?portfolioHealth wm:riskScore ?riskScore .
    }
    GROUP BY ?investorId
  }

  # Join all the calculated averages
  BIND(wm:Investor ?investor)
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?avgTotalHoldingValue ?avgHoldingReturn ?avgTotalRebalanceAmount ?avgScenarioAllocationShift
WHERE {
  ?investor wm:hasRiskTolerance ?riskTolerance .

  # Calculate average total holding value
  {
    SELECT ?investorId ?totalHoldingValue
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currentValue .
      ?holding wm:heldByInvestor ?investorId .
      BIND (?cost + ?currentValue AS ?totalHoldingValue)
    }
    GROUP BY ?investorId
  } AS ?holdingValues

  BIND (AVG(?holdingValues.totalHoldingValue) AS ?avgTotalHoldingValue)

  # Calculate average holding return
  {
    SELECT ?investorId ?holdingReturn
    WHERE {
      ?investor wm:hasHolding ?holding .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currentValue .
      ?holding wm:heldByInvestor ?investorId .
      BIND (((?currentValue - ?cost) / ?cost) AS ?holdingReturn)
    }
    GROUP BY ?investorId
  } AS ?holdingReturns

  BIND (AVG(?holdingReturns.holdingReturn) AS ?avgHoldingReturn)

  # Calculate average total rebalance amount
  {
    SELECT ?investorId ?totalRebalanceAmount
    WHERE {
      ?investor wm:hasRebalancingAction ?rebalancingAction .
      ?rebalancingAction wm:amount ?amount .
      ?rebalancingAction wm:rebalancingActionOfInvestor ?investorId .
      BIND (?amount AS ?totalRebalanceAmount)
    }
    GROUP BY ?investorId
  } AS ?rebalanceAmounts

  BIND (AVG(?rebalanceAmounts.totalRebalanceAmount) AS ?avgTotalRebalanceAmount)

  # Calculate average scenario allocation shift
  {
    SELECT ?investorId ?scenarioAllocationShift
    WHERE {
      ?investor wm:hasScenarioRebalancing ?scenarioRebalancing .
      ?scenarioRebalancing wm:currentAllocationPct ?currentAllocationPct .
      ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investorId .
      BIND ((?newAllocationPct - ?currentAllocationPct) AS ?scenarioAllocationShift)
    }
    GROUP BY ?investorId
  } AS ?allocationShifts

  BIND (AVG(?allocationShifts.scenarioAllocationShift) AS ?avgScenarioAllocationShift)

  ?riskTolerance rdfs:label ?riskToleranceLabel .
}
GROUP BY ?riskTolerance
ORDER BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:investorId ?investorId .
      ?cashFlow wm:amount ?amount .
      FILTER (?amount < 0)  # Inflows are negative
    }
    GROUP BY ?investorId
    BIND (SUM(?amount) AS ?netCashFlow)
  }

  # Calculate total rebalance amount
  OPTIONAL {
    SELECT ?investorId ?totalRebalanceAmount
    WHERE {
      ?rebalancingAction a wm:RebalancingAction .
      ?rebalancingAction wm:rebalancingActionOfInvestor ?investor .
      ?rebalancingAction wm:investorId ?investorId .
      ?rebalancingAction wm:amount ?amount .
    }
    GROUP BY ?investorId
    BIND (SUM(ABS(?amount)) AS ?totalRebalanceAmount)
  }

  # Calculate average goal shortfall
  OPTIONAL {
    SELECT ?investorId ?avgGoalShortfall
    WHERE {
      ?investmentGoal a wm:InvestmentGoal .
      ?investmentGoal wm:belongsToInvestor ?investor .
      ?investmentGoal wm:investorId ?investorId .
      ?investmentGoal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
    BIND (AVG(?shortfall) AS ?avgGoalShortfall)
  }

  BIND (COALESCE(?netCashFlow, 0) + COALESCE(?totalRebalanceAmount, 0) - COALESCE(?avgGoalShortfall, 0) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
