    BIND (AVG(?shortfall) AS ?avgGoalShortfall)
  }

  BIND (COALESCE(?netCashFlow, 0) + COALESCE(?totalSectorInvestment, 0) - COALESCE(?avgGoalShortfall, 0) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
    ?cashFlow wm:cashFlowOfInvestor ?investor .
    ?cashFlow wm:amount ?amount .
    ?cashFlow wm:type ?type .
    BIND(IF(STRSTARTS(STR(?type), "Deposit") || STRSTARTS(STR(?type), "SIP"), -?amount, ?amount) AS ?netCashFlow)
  }

  # Calculate total sector investment
  OPTIONAL {
    ?holding wm:heldByInvestor ?investor .
    ?holding wm:sector ?sector .
    ?holding wm:currentValue ?currentValue .
    BIND(?currentValue AS ?sectorInvestment)
  }

  # Calculate risk score
  OPTIONAL {
    ?health wm:healthOfInvestor ?investor .
    ?health wm:riskScore ?riskScore .
  }

  # Min-max normalization and composite score calculation
  FILTER (
    (?netCashFlow != 0 || ?sectorInvestment != 0 || ?riskScore != 0)
  )

  # Calculate min and max values for normalization
  VALUES (?minNetCashFlow ?maxNetCashFlow) {
    (0 0)  # Default values if no cash flows are found
  }
  VALUES (?minSectorInvestment ?maxSectorInvestment) {
    (0 0)  # Default values if no sector investments are found
  }
  VALUES (?minRiskScore ?maxRiskScore) {
    (0 100)
  }

  BIND(
    IF(
      ?maxNetCashFlow != 0,
      (?netCashFlow - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow),
      0
    ) AS ?normalizedNetCashFlow
  )
  BIND(
    IF(
      ?maxSectorInvestment != 0,
      (?sectorInvestment - ?minSectorInvestment) / (?maxSectorInvestment - ?minSectorInvestment),
      0
    ) AS ?normalizedSectorInvestment
  )
  BIND(
    IF(
      ?maxRiskScore != 0,
      (?riskScore - ?minRiskScore) / (?maxRiskScore - ?minRiskScore),
      0
    ) AS ?normalizedRiskScore
  )

  BIND(
    100 * ((?normalizedNetCashFlow + ?normalizedSectorInvestment + ?normalizedRiskScore) / 3) AS ?compositeScore
  )
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?amount .
      FILTER (?amount < 0)  # Inflows are negative
    }
    GROUP BY ?investorId
    BIND (SUM(?amount) AS ?netCashFlow)
  }

  # Calculate total scenario allocation shift
  OPTIONAL {
    SELECT ?investorId ?allocationShift
    WHERE {
      ?scenarioRebalancing a wm:ScenarioRebalancing .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor .
      ?scenarioRebalancing wm:currentAllocationPct ?currentAllocationPct .
      ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
    BIND (SUM(?newAllocationPct - ?currentAllocationPct) AS ?allocationShift)
  }

  # Calculate average goal shortfall
  OPTIONAL {
    SELECT ?investorId ?avgGoalShortfall
    WHERE {
      ?investmentGoal a wm:InvestmentGoal .
      ?investmentGoal wm:belongsToInvestor ?investor .
      ?investmentGoal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
    BIND (AVG(?shortfall) AS ?avgGoalShortfall)
  }

  # Calculate composite score
  FILTER (ISNUM(?netCashFlow) && ISNUM(?allocationShift) && ISNUM(?avgGoalShortfall))
  BIND (
    (
      (
        (
          (?netCashFlow - MIN(?netCashFlow)) / (?netCashFlow - MAX(?netCashFlow))
        )
      ) +
      (
        (
          (?allocationShift - MIN(?allocationShift)) / (?allocationShift - MAX(?allocationShift))
        )
      ) +
      (
        (
          1 - ((?avgGoalShortfall - MIN(?avgGoalShortfall)) / (?avgGoalShortfall - MAX(?avgGoalShortfall)))
        )
      )
    ) / 3 * 100 AS ?compositeScore
  )
}
ORDER BY ?compositeScore DESC ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?amount .
      FILTER (?amount < 0)  # Inflows are negative
      BIND (?amount AS ?netCashFlow)
    }
    GROUP BY ?investorId ?netCashFlow
  }

  # Calculate risk score
  OPTIONAL {
    ?portfolioHealth a wm:PortfolioHealth .
    ?portfolioHealth wm:healthOfInvestor ?investor .
    ?portfolioHealth wm:riskScore ?riskScore .
  }

  # Calculate average goal shortfall
  OPTIONAL {
    SELECT ?investorId ?avgGoalShortfall
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:shortfall ?shortfall .
      BIND (?shortfall AS ?avgGoalShortfall)
    }
    GROUP BY ?investorId ?avgGoalShortfall
  }

  # Normalize net cash flow (0-1)
  BIND(IF(BOUND(?netCashFlow), (0 - ?netCashFlow) / (ABS(?netCashFlow) + 1e-9), 0) AS ?normalizedNetCashFlow)

  # Normalize risk score (0-1)
  BIND(IF(BOUND(?riskScore), (100 - ?riskScore) / 100, 0) AS ?normalizedRiskScore)

  # Normalize average goal shortfall (0-1, invert)
  BIND(IF(BOUND(?avgGoalShortfall), 1 - (?avgGoalShortfall / (ABS(?avgGoalShortfall) + 1e-9)), 0) AS ?normalizedAvgGoalShortfall)

  # Calculate composite score
  BIND((?normalizedNetCashFlow + ?normalizedRiskScore + ?normalizedAvgGoalShortfall) / 3 * 100 AS ?compositeScore)

  FILTER EXISTS { ?cashFlow a wm:CashFlow . ?cashFlow wm:cashFlowOfInvestor ?investor . }
  FILTER EXISTS { ?portfolioHealth a wm:PortfolioHealth . ?portfolioHealth wm:healthOfInvestor ?investor . }
  FILTER EXISTS { ?goal a wm:InvestmentGoal . ?goal wm:belongsToInvestor ?investor . }
}
ORDER BY DESC(?compositeScore)
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?amount .
      FILTER (?amount < 0)  # Inflows are negative
    }
    GROUP BY ?investorId
    BIND (SUM(?amount) AS ?netCashFlow)
  }

  # Calculate total holding gain
  OPTIONAL {
    SELECT ?investorId ?totalHoldingGain
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currentValue .
      FILTER (xsd:decimal(?cost) != 0 && xsd:decimal(?currentValue) != 0)
    }
    GROUP BY ?investorId
    BIND (SUM(?currentValue - ?cost) AS ?totalHoldingGain)
  }

  # Calculate total rebalance amount
  OPTIONAL {
    SELECT ?investorId ?totalRebalanceAmount
    WHERE {
      ?rebalance a wm:RebalancingAction .
      ?rebalance wm:rebalancingActionOfInvestor ?investor .
      ?rebalance wm:amount ?amount .
    }
    GROUP BY ?investorId
    BIND (SUM(ABS(?amount)) AS ?totalRebalanceAmount)
  }

  # Calculate total scenario allocation shift
  OPTIONAL {
    SELECT ?investorId ?totalScenarioAllocationShift
    WHERE {
      ?scenario a wm:ScenarioRebalancing .
      ?scenario wm:scenarioRebalancingOfInvestor ?investor .
      ?scenario wm:currentAllocationPct ?currentAllocationPct .
      ?scenario wm:newAllocationPct ?newAllocationPct .
    }
    GROUP BY ?investorId
    BIND (SUM(ABS(?newAllocationPct - ?currentAllocationPct)) AS ?totalScenarioAllocationShift)
  }

  # Filter for investors with all 4 components
  FILTER (BOUND(?netCashFlow) && BOUND(?totalHoldingGain) && BOUND(?totalRebalanceAmount) && BOUND(?totalScenarioAllocationShift))

  # Min-max normalization and composite score calculation
  BIND (
    (
      (?netCashFlow - (SELECT MIN(?netCashFlow) FROM wm:CashFlow WHERE { ?cf a wm:CashFlow })) /
      ((SELECT MAX(?netCashFlow) FROM wm:CashFlow WHERE { ?cf a wm:CashFlow }) - (SELECT MIN(?netCashFlow) FROM wm:CashFlow WHERE { ?cf a wm:CashFlow }))
    ) AS ?normalizedNetCashFlow
  )
  BIND (
    (
      (?totalHoldingGain - (SELECT MIN(?totalHoldingGain) FROM wm:PortfolioHolding WHERE { ?ph a wm:PortfolioHolding })) /
      ((SELECT MAX(?totalHoldingGain) FROM wm:PortfolioHolding WHERE { ?ph a wm:PortfolioHolding }) - (SELECT MIN(?totalHoldingGain) FROM wm:PortfolioHolding WHERE { ?ph a wm:PortfolioHolding }))
    ) AS ?normalizedTotalHoldingGain
  )
  BIND (
    (
      (?totalRebalanceAmount - (SELECT MIN(?totalRebalanceAmount) FROM wm:RebalancingAction WHERE { ?ra a wm:RebalancingAction })) /
      ((SELECT MAX(?totalRebalanceAmount) FROM wm:RebalancingAction WHERE { ?ra a wm:RebalancingAction }) - (SELECT MIN(?totalRebalanceAmount) FROM wm:RebalancingAction WHERE { ?ra a wm:RebalancingAction }))
    ) AS ?normalizedTotalRebalanceAmount
  )
  BIND (
    (
      (?totalScenarioAllocationShift - (SELECT MIN(?totalScenarioAllocationShift) FROM wm:ScenarioRebalancing WHERE { ?sr a wm:ScenarioRebalancing })) /
      ((SELECT MAX(?totalScenarioAllocationShift) FROM wm:ScenarioRebalancing WHERE { ?sr a wm:ScenarioRebalancing }) - (SELECT MIN(?totalScenarioAllocationShift) FROM wm:ScenarioRebalancing WHERE { ?sr a wm:ScenarioRebalancing }))
    ) AS ?normalizedTotalScenarioAllocationShift
  )

  BIND (100 * ((?normalizedNetCashFlow + ?normalizedTotalHoldingGain + ?normalizedTotalRebalanceAmount + ?normalizedTotalScenarioAllocationShift) / 4) AS ?compositeScore)
}
ORDER BY ?compositeScore DESC
LIMIT 10

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
    ?cashFlow a wm:CashFlow .
    ?cashFlow wm:cashFlowOfInvestor ?investor .
    ?cashFlow wm:amount ?cashFlowAmount .
    BIND (?cashFlowAmount AS ?netCashFlow)
  }

  # Calculate total holding gain
  OPTIONAL {
    ?holding a wm:PortfolioHolding .
    ?holding wm:heldByInvestor ?investor .
    ?holding wm:cost ?holdingCost .
    ?holding wm:currentValue ?holdingCurrentValue .
    FILTER (xsd:decimal(?holdingCost) != 0)
    FILTER (xsd:decimal(?holdingCurrentValue) != 0)
    BIND ((?holdingCurrentValue - ?holdingCost) AS ?holdingGain)
    BIND (SUM(?holdingGain) AS ?totalHoldingGain)
  }

  # Calculate total sector investment
  OPTIONAL {
    ?sectorAllocation a wm:SectorAllocation .
    ?sectorAllocation wm:allocationOfInvestor ?investor .
    ?sectorAllocation wm:allocationPct ?sectorAllocationPct .
    BIND (SUM(?sectorAllocationPct) AS ?totalSectorInvestment)
  }

  # Calculate risk score
  OPTIONAL {
    ?portfolioHealth a wm:PortfolioHealth .
    ?portfolioHealth wm:healthOfInvestor ?investor .
    ?portfolioHealth wm:riskScore ?riskScore .
    BIND (?riskScore AS ?riskScore)
  }

  # Filter for investors with all 4 components
  FILTER (BOUND(?netCashFlow))
  FILTER (BOUND(?totalHoldingGain))
  FILTER (BOUND(?totalSectorInvestment))
  FILTER (BOUND(?riskScore))

  # Min-max normalization
  BIND (xsd:decimal(?netCashFlow) AS ?netCashFlowDecimal)
  BIND (xsd:decimal(?totalHoldingGain) AS ?totalHoldingGainDecimal)
  BIND (xsd:decimal(?totalSectorInvestment) AS ?totalSectorInvestmentDecimal)
  BIND (xsd:decimal(?riskScore) AS ?riskScoreDecimal)

  # Find min and max values for normalization
  OPTIONAL {
    SELECT (MIN(?netCashFlowDecimal) AS ?minNetCashFlow) WHERE {
      ?investor2 a wm:Investor .
      ?cashFlow2 a wm:CashFlow .
      ?cashFlow2 wm:cashFlowOfInvestor ?investor2 .
      ?cashFlow2 wm:amount ?netCashFlowDecimal .
    }
  }
  OPTIONAL {
    SELECT (MAX(?netCashFlowDecimal) AS ?maxNetCashFlow) WHERE {
      ?investor2 a wm:Investor .
      ?cashFlow2 a wm:CashFlow .
      ?cashFlow2 wm:cashFlowOfInvestor ?investor2 .
      ?cashFlow2 wm:amount ?netCashFlowDecimal .
    }
  }
  OPTIONAL {
    SELECT (MIN(?totalHoldingGainDecimal) AS ?minTotalHoldingGain) WHERE {
      ?investor2 a wm:Investor .
      ?holding2 a wm:PortfolioHolding .
      ?holding2 wm:heldByInvestor ?investor2 .
      ?holding2 wm:cost ?holdingCost2 .
      ?holding2 wm:currentValue ?holdingCurrentValue2 .
      FILTER (xsd:decimal(?holdingCost2) != 0)
      FILTER (xsd:decimal(?holdingCurrentValue2) != 0)
      BIND ((?holdingCurrentValue2 - ?holdingCost2) AS ?holdingGain2)
      BIND (SUM(?holdingGain2) AS ?totalHoldingGainDecimal)
    }
  }
  OPTIONAL {
    SELECT (MAX(?totalHoldingGainDecimal) AS ?maxTotalHoldingGain) WHERE {
      ?investor2 a wm:Investor .
      ?holding2 a wm:PortfolioHolding .
      ?holding2 wm:heldByInvestor ?investor2 .
      ?holding2 wm:cost ?holdingCost2 .
      ?holding2 wm:currentValue ?holdingCurrentValue2 .
      FILTER (xsd:decimal(?holdingCost2) != 0)
      FILTER (xsd:decimal(?holdingCurrentValue2) != 0)
      BIND ((?holdingCurrentValue2 - ?holdingCost2) AS ?holdingGain2)
      BIND (SUM(?holdingGain2) AS ?totalHoldingGainDecimal)
    }
  }
  OPTIONAL {
    SELECT (MIN(?totalSectorInvestmentDecimal) AS ?minTotalSectorInvestment) WHERE {
      ?investor2 a wm:Investor .
      ?sectorAllocation2 a wm:SectorAllocation .
      ?sectorAllocation2 wm:allocationOfInvestor ?investor2 .
      ?sectorAllocation2 wm:allocationPct ?sectorAllocationPct2 .
      BIND (SUM(?sectorAllocationPct2) AS ?totalSectorInvestmentDecimal)
    }
  }
  OPTIONAL {
    SELECT (MAX(?totalSectorInvestmentDecimal) AS ?maxTotalSectorInvestment) WHERE {
      ?investor2 a wm:Investor .
      ?sectorAllocation2 a wm:SectorAllocation .
      ?sectorAllocation2 wm:allocationOfInvestor ?investor2 .
      ?sectorAllocation2 wm:allocationPct ?sectorAllocationPct2 .
      BIND (SUM(?sectorAllocationPct2) AS ?totalSectorInvestmentDecimal)
    }
  }
  OPTIONAL {
    SELECT (MIN(?riskScoreDecimal) AS ?minRiskScore) WHERE {
      ?investor2 a wm:Investor .
      ?portfolioHealth2 a wm:PortfolioHealth .
      ?portfolioHealth2 wm:healthOfInvestor ?investor2 .
      ?portfolioHealth2 wm:riskScore ?riskScoreDecimal .
    }
  }
  OPTIONAL {
    SELECT (MAX(?riskScoreDecimal) AS ?maxRiskScore) WHERE {
      ?investor2 a wm:Investor .
      ?portfolioHealth2 a wm:PortfolioHealth .
      ?portfolioHealth2 wm:healthOfInvestor ?investor2 .
      ?portfolioHealth2 wm:riskScore ?riskScoreDecimal .
    }
  }

  # Normalize components
  BIND ((?netCashFlowDecimal - ?minNetCashFlow) / (?maxNetCashFlow - ?minNetCashFlow) AS ?normalizedNetCashFlow)
  BIND ((?totalHoldingGainDecimal - ?minTotalHoldingGain) / (?maxTotalHoldingGain - ?minTotalHoldingGain) AS ?normalizedTotalHoldingGain)
  BIND ((?totalSectorInvestmentDecimal - ?minTotalSectorInvestment) / (?maxTotalSectorInvestment - ?minTotalSectorInvestment) AS ?normalizedTotalSectorInvestment)
  BIND ((?riskScoreDecimal - ?minRiskScore) / (?maxRiskScore - ?minRiskScore) AS ?normalizedRiskScore)

  # Calculate composite score
  BIND ((?normalizedNetCashFlow + ?normalizedTotalHoldingGain + ?normalizedTotalSectorInvestment + ?normalizedRiskScore) / 4 * 100 AS ?compositeScore)
}
ORDER BY ?compositeScore DESC
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:investorId ?investorId .
      ?cashFlow wm:amount ?amount .
      FILTER (?amount < 0)  # Inflows are negative
    }
    GROUP BY ?investorId
    BIND (SUM(?amount) AS ?netCashFlow)
  }

  # Calculate total rebalance amount
  OPTIONAL {
    SELECT ?investorId ?totalRebalanceAmount
    WHERE {
      ?rebalancingAction a wm:RebalancingAction .
      ?rebalancingAction wm:rebalancingActionOfInvestor ?investor .
      ?rebalancingAction wm:investorId ?investorId .
      ?rebalancingAction wm:amount ?amount .
    }
    GROUP BY ?investorId
    BIND (SUM(ABS(?amount)) AS ?totalRebalanceAmount)
  }

  # Calculate total sector investment
  OPTIONAL {
    SELECT ?investorId ?totalSectorInvestment
    WHERE {
      ?sectorAllocation a wm:SectorAllocation .
      ?sectorAllocation wm:allocationOfInvestor ?investor .
      ?sectorAllocation wm:investorId ?investorId .
      ?sectorAllocation wm:totalInvestment ?totalInvestment .
    }
    GROUP BY ?investorId
    BIND (SUM(?totalInvestment) AS ?totalSectorInvestment)
  }

  # Calculate average goal shortfall
  OPTIONAL {
    SELECT ?investorId ?avgGoalShortfall
    WHERE {
      ?investmentGoal a wm:InvestmentGoal .
      ?investmentGoal wm:belongsToInvestor ?investor .
      ?investmentGoal wm:investorId ?investorId .
      ?investmentGoal wm:shortfall ?shortfall .
    }
    GROUP BY ?investorId
    BIND (AVG(?shortfall) AS ?avgGoalShortfall)
  }

  BIND (COALESCE(?netCashFlow, 0) + COALESCE(?totalRebalanceAmount, 0) + COALESCE(?totalSectorInvestment, 0) - COALESCE(?avgGoalShortfall, 0) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?amount .
      FILTER (?amount < 0)  # Inflows are negative
      BIND (?amount AS ?inflow)
    }
    UNION
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?amount .
      FILTER (?amount > 0)  # Outflows are positive
      BIND (?amount AS ?outflow)
    }
    BIND (?inflow + ?outflow AS ?netCashFlow)
  }

  # Calculate total rebalance amount
  OPTIONAL {
    SELECT ?investorId ?totalRebalanceAmount
    WHERE {
      ?rebalancingAction a wm:RebalancingAction .
      ?rebalancingAction wm:rebalancingActionOfInvestor ?investor .
      ?rebalancingAction wm:amount ?amount .
      BIND (?amount AS ?totalRebalanceAmount)
    }
  }

  # Calculate total scenario allocation shift
  OPTIONAL {
    SELECT ?investorId ?totalScenarioAllocationShift
    WHERE {
      ?scenarioRebalancing a wm:ScenarioRebalancing .
      ?scenarioRebalancing wm:scenarioRebalancingOfInvestor ?investor .
      ?scenarioRebalancing wm:currentAllocationPct ?currentAllocationPct .
      ?scenarioRebalancing wm:newAllocationPct ?newAllocationPct .
      BIND ((?newAllocationPct - ?currentAllocationPct) AS ?allocationShift)
      BIND (SUM(?allocationShift) AS ?totalScenarioAllocationShift)
    }
  }

  # Calculate average goal shortfall
  OPTIONAL {
    SELECT ?investorId ?avgGoalShortfall
    WHERE {
      ?investmentGoal a wm:InvestmentGoal .
      ?investmentGoal wm:belongsToInvestor ?investor .
      ?investmentGoal wm:targetAmount ?targetAmount .
      ?investmentGoal wm:currentValue ?currentValue .
      BIND (?targetAmount - ?currentValue AS ?goalShortfall)
      BIND (AVG(?goalShortfall) AS ?avgGoalShortfall)
    }
  }

  # Calculate composite score
  FILTER (
    (?netCashFlow != 0 || ?totalRebalanceAmount != 0 || ?totalScenarioAllocationShift != 0 || ?avgGoalShortfall != 0)
  )

  # Min-max normalization
  BIND (
    IF(
      ?netCashFlow = 0,
      0,
      (?netCashFlow - MIN(?netCashFlow)) / (?netCashFlow - MIN(?netCashFlow))
    ) AS ?normalizedNetCashFlow
  )
  BIND (
    IF(
      ?totalRebalanceAmount = 0,
      0,
      (?totalRebalanceAmount - MIN(?totalRebalanceAmount)) / (?totalRebalanceAmount - MIN(?totalRebalanceAmount))
    ) AS ?normalizedRebalanceAmount
  )
  BIND (
    IF(
      ?totalScenarioAllocationShift = 0,
      0,
      (?totalScenarioAllocationShift - MIN(?totalScenarioAllocationShift)) / (?totalScenarioAllocationShift - MIN(?totalScenarioAllocationShift))
    ) AS ?normalizedScenarioAllocationShift
  )
  BIND (
    IF(
      ?avgGoalShortfall = 0,
      0,
      1 - ((?avgGoalShortfall - MIN(?avgGoalShortfall)) / (?avgGoalShortfall - MIN(?avgGoalShortfall)))
    ) AS ?normalizedGoalShortfall
  )

  BIND (
    100 * ((?normalizedNetCashFlow + ?normalizedRebalanceAmount + ?normalizedScenarioAllocationShift + ?normalizedGoalShortfall) / 4) AS ?compositeScore
  )
}
ORDER BY DESC(?compositeScore)
LIMIT 10

