PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?compositeScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .

  # Calculate net cash flow
  OPTIONAL {
    SELECT ?investorId ?netCashFlow
    WHERE {
      ?cashFlow a wm:CashFlow .
      ?cashFlow wm:cashFlowOfInvestor ?investor .
      ?cashFlow wm:amount ?amount .
      BIND(IF(?cashFlow wm:type "Deposit", -?amount, ?amount) AS ?netCashFlow)
    }
  }

  # Calculate total holding gain
  OPTIONAL {
    SELECT ?investorId ?holdingGain
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:cost ?cost .
      ?holding wm:currentValue ?currentValue .
      FILTER (xsd:decimal(?cost) != 0 && xsd:decimal(?currentValue) != 0)
      BIND(?currentValue - ?cost AS ?holdingGain)
    }
  }

  # Calculate total sector investment
  OPTIONAL {
    SELECT ?investorId ?sectorInvestment
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:heldByInvestor ?investor .
      ?holding wm:currentValue ?currentValue .
      BIND(?currentValue AS ?sectorInvestment)
    }
  }

  # Calculate average goal shortfall
  OPTIONAL {
    SELECT ?investorId ?avgGoalShortfall
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:targetAmount ?targetAmount .
      ?goal wm:currentValue ?currentValue .
      BIND(?targetAmount - ?currentValue AS ?goalShortfall)
    }
    GROUP BY ?investorId
    BIND(AVG(?goalShortfall) AS ?avgGoalShortfall)
  }

  BIND(COALESCE(?netCashFlow, 0) + COALESCE(?holdingGain, 0) + COALESCE(?sectorInvestment, 0) - COALESCE(?avgGoalShortfall, 0) AS ?compositeScore)
}
ORDER BY DESC(?compositeScore) ?investorId
LIMIT 10

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT (COUNT(DISTINCT ?investorId) AS ?count)
WHERE {
  ?goal a wm:InvestmentGoal .
  ?goal wm:belongsToInvestor ?investor .
  ?investor wm:investorId ?investorId .

  OPTIONAL {
    ?rebalance a wm:RebalancingAction .
    ?rebalance wm:rebalancingActionOfInvestor ?investor .
  }

  FILTER (!BOUND(?rebalance))
}

