SELECT ?sector ?avgDividends
WHERE {
  ?holding a wm:PortfolioHolding .
  ?holding wm:sector ?sector .
  ?holding wm:dividends ?dividends .
  {
    SELECT ?sector AVG(?dividends) AS ?avgDividends
    WHERE {
      ?holding a wm:PortfolioHolding .
      ?holding wm:sector ?sector .
      ?holding wm:dividends ?dividends .
    }
    GROUP BY ?sector
  }
}

