PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?riskTolerance ?avgSharpeRatio
WHERE {
  WITH {
    ?goal a wm:InvestmentGoal .
    ?goal wm:belongsToInvestor ?investor .
    ?investor wm:hasRiskTolerance ?riskTolerance .
  }
  SELECT ?investor ?avgSharpeRatio
  WHERE {
    ?goal a wm:InvestmentGoal .
    ?goal wm:belongsToInvestor ?investor .
    ?investor wm:hasRiskTolerance ?riskTolerance .
    ?goal wm:avgSharpeRatio ?sharpeRatio .
    BIND (AVG(?sharpeRatio) AS ?avgSharpeRatio)
  }
  GROUP BY ?investor ?riskTolerance
}
GROUP BY ?riskTolerance

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment ?avg_progress_pct ?n_investors
WHERE {
  WITH {
    ?goal_segment a wm:InvestmentGoal .
    ?goal_segment wm:belongsToInvestor ?investor .
    ?investor wm:segment ?segment .
    ?goal_segment wm:progressPct ?progress_pct .
  }
  SELECT ?segment (AVG(?progress_pct) AS ?avg_progress_pct) (COUNT(DISTINCT ?investor) AS ?n_investors)
  WHERE {
    ?goal_segment a wm:InvestmentGoal .
    ?goal_segment wm:belongsToInvestor ?investor .
    ?investor wm:segment ?segment .
    ?goal_segment wm:progressPct ?progress_pct .
  }
  GROUP BY ?segment
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?segment ?avgSharpeRatio
WHERE {
  WITH {
    ?goal a wm:InvestmentGoal .
    ?goal wm:belongsToInvestor ?investor .
    ?investor wm:segment ?segment .
  }
  ?goal wm:avgSharpeRatio ?sharpeRatio .
  ?investor wm:segment ?segment .
  SELECT ?segment (AVG(?sharpeRatio) AS ?avgSharpeRatio)
  WHERE {
    ?goal a wm:InvestmentGoal .
    ?goal wm:belongsToInvestor ?investor .
    ?investor wm:segment ?segment .
    ?goal wm:avgSharpeRatio ?sharpeRatio .
  }
  GROUP BY ?segment
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?avgProgressPct ?avgRiskScore
WHERE {
  ?investor a wm:Investor .
  ?investor wm:segment "Moderate" .
  ?investor wm:investorId ?investorId .
  ?goal a wm:InvestmentGoal .
  ?goal wm:belongsToInvestor ?investor .
  ?goal wm:progressPct ?progressPct .
  ?health a wm:PortfolioHealth .
  ?health wm:healthOfInvestor ?investor .
  ?health wm:riskScore ?riskScore .

  {
    SELECT AVG(?progressPct) AS ?avgProgressPct
    WHERE {
      ?goal a wm:InvestmentGoal .
      ?goal wm:belongsToInvestor ?investor .
      ?goal wm:progressPct ?progressPct .
    }
  }
  {
    SELECT AVG(?riskScore) AS ?avgRiskScore
    WHERE {
      ?health a wm:PortfolioHealth .
      ?health wm:healthOfInvestor ?investor .
      ?health wm:riskScore ?riskScore .
    }
  }

  FILTER (?avgProgressPct < 30)
  FILTER (?avgRiskScore > 50)
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT ?investorId ?avg_progress_pct ?avg_dividends ?avg_liquidity_score
WHERE {
  ?investor a wm:Investor .
  ?investor wm:investorId ?investorId .
  ?investor wm:riskTolerance "Aggressive" .
  ?investor wm:hasInvestmentGoal ?investmentGoal .
  ?investmentGoal wm:progressPct ?progressPct .
  ?investor wm:hasHolding ?portfolioHolding .
  ?portfolioHolding wm:dividends ?dividends .
  ?investor wm:hasPortfolioHealth ?portfolioHealth .
  ?portfolioHealth wm:liquidityScore ?liquidityScore .

  {
    SELECT AVG(?progressPct) AS ?avg_progress_pct
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:riskTolerance "Aggressive" .
      ?investor wm:hasInvestmentGoal ?investmentGoal .
      ?investmentGoal wm:progressPct ?progressPct .
    }
  }
  {
    SELECT AVG(?dividends) AS ?avg_dividends
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:riskTolerance "Aggressive" .
      ?investor wm:hasHolding ?portfolioHolding .
      ?portfolioHolding wm:dividends ?dividends .
    }
  }
  {
    SELECT AVG(?liquidityScore) AS ?avg_liquidity_score
    WHERE {
      ?investor a wm:Investor .
      ?investor wm:investorId ?investorId .
      ?investor wm:riskTolerance "Aggressive" .
      ?investor wm:hasPortfolioHealth ?portfolioHealth .
      ?portfolioHealth wm:liquidityScore ?liquidityScore .
    }
  }

  FILTER (?avg_progress_pct > 30)
  FILTER (?avg_dividends < 14000)
  FILTER (?avg_liquidity_score < 50)
}

