SELECT SUM(wm:amount) AS ?totalNetCashFlow
WHERE {
  ?investor a wm:Investor ;
            wm:hasCategory ?category .
  ?category a wm:Category ;
            rdfs:label "Hybrid" .
  ?investor wm:hasCashFlow ?cashFlow .
  ?cashFlow a wm:CashFlow ;
            wm:amount ?amount .
}

PREFIX wm: <https://wealth.example.org/ontology/>
SELECT SUM(?amount) AS ?totalNetCashFlow
WHERE {
  ?investor a wm:Investor .
  ?holding a wm:PortfolioHolding ;
    wm:heldByInvestor ?investor ;
    wm:investmentType "Gold" .
  ?cashFlow a wm:CashFlow ;
    wm:cashFlowOfInvestor ?investor ;
    wm:date ?date .
  FILTER(YEAR(?date) = 2024)
  BIND(IF(?cashFlow.type = "Deposit", -?cashFlow.amount, ?cashFlow.amount) AS ?amount)
}

